// ── AI Qualifier ─────────────────────────────────────────────
// Deterministic intent scoring with an optional LLM upgrade.
// To upgrade: send $json.llm_prompt to OpenAI (chat/completions) and
// replace `score`/`reasons` with the model's JSON response.

const lead = $input.first().json;
const msg = (lead.message || '').toLowerCase();
const domain = (lead.email.split('@')[1] || '').toLowerCase();
const freeMail = /(gmail|yahoo|hotmail|outlook|icloud)\./.test(domain);
const reasons = [];
let score = 42;

// 1. Budget signal
if (/budget|pricing|quote|cost|\$\d|approved/.test(msg)) {
  score += 25; reasons.push('Budget/pricing language (+25)');
} else { reasons.push('No budget signal (+0)'); }

// 2. Urgency signal
if (/asap|urgent|this week|immediately|today|move fast|deadline/.test(msg)) {
  score += 20; reasons.push('Urgency language (+20)');
}

// 3. Domain quality
if (domain && !freeMail) { score += 15; reasons.push('Corporate domain (+15)'); }
else if (freeMail) { reasons.push('Free-mail domain (+0)'); }

// 4. Source weighting
const ref = /referral|partner/i.test(lead.source);
const paid = /ads|campaign/i.test(lead.source);
if (ref) { score += 10; reasons.push('Referral source (+10)'); }
else if (paid) { score += 5; reasons.push('Paid source (+5)'); }

// 5. Effort signal
if (msg.length > 140) { score += 8; reasons.push('Detailed inquiry (+8)'); }

score = Math.max(0, Math.min(100, score));
const route = score >= 80 ? 'hot' : score >= 55 ? 'warm' : 'cold';

// Pre-built LLM prompt (for the optional upgrade):
const llm_prompt =
  'You are a lead-qualification engine. Score this inbound lead 0-100 on ' +
  'purchase intent given: budget signals, urgency, business fit, effort. ' +
  'Respond ONLY with JSON {"score": <int>, "reasons": [string], "route": ' +
  '"hot|warm|cold"} where hot>=80, warm>=55.\n\nLEAD:\n' +
  JSON.stringify(lead, null, 2);

return [{ json: {
  ...lead,
  score,
  route,
  reasons,
  llm_prompt,
  domain,
  qualified_at: new Date().toISOString()
} }];

